// --- Main App ---

const AppContent = () => {
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatTrigger, setChatTrigger] = useState('');
  const [activeModals, setActiveModals] = useState({
    scan: false,
    bookings: false,
    wallet: false,
    notifications: false
  });

  const toggleModal = (key: keyof typeof activeModals) => {
    setActiveModals(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const contextValue = {
    isOpen: isChatOpen,
    openChat: (msg?: string) => {
      setIsChatOpen(true);
      if(msg) setChatTrigger(msg);
    },
    closeChat: () => setIsChatOpen(false),
    toggleWallet: () => toggleModal('wallet'),
    toggleNotifications: () => toggleModal('notifications'),
    toggleScan: () => toggleModal('scan'),
    toggleBookings: () => toggleModal('bookings'),
    openDoctorBooking: () => toggleModal('bookings')
  };

  return (
    <ChatContext.Provider value={contextValue}>
      <HashRouter>
         <Routes>
           <Route path="/" element={<HomePage />} />
           <Route path="/catalog/:type" element={<CatalogPage />} />
           <Route path="/institution/:id" element={<InstitutionPage />} />
           <Route path="/pass" element={<FamilyPassPage />} />
           <Route path="/health" element={<HealthPage />} />
           <Route path="/profile" element={<ProfilePage />} />
           <Route path="/market" element={<MarketPage />} />
           <Route path="/admin/*" element={<AdminDashboard />} />
         </Routes>
         <BottomNav />
         <AIAssistant triggerMsg={chatTrigger} onClearTrigger={() => setChatTrigger('')} />

         {activeModals.scan && <ScanModal onClose={() => toggleModal('scan')} />}
         {activeModals.bookings && <BookingsModal onClose={() => toggleModal('bookings')} />}
         {activeModals.wallet && <WalletModal onClose={() => toggleModal('wallet')} />}
         {activeModals.notifications && <NotificationsModal onClose={() => toggleModal('notifications')} />}
      </HashRouter>
    </ChatContext.Provider>
  );
};

export default function App() {
  const [language, setLanguage] = useState<Language>('ru');

  return (
    <LanguageContext.Provider value={{
      language,
      setLanguage,
      t: (key) => translations[language][key] || key
    }}>
      <AppContent />
    </LanguageContext.Provider>
  );
}
